// watchDetectFixture opens a real store for the watch detector tests (the
// recsJanitorFixture posture — the detector/store joint runs on real
// instances, never a fake).
func watchDetectFixture(t *testing.T) (*store.Store, context.Context) {
	t.Helper()
	ctx := context.Background()
	st, err := store.Open(ctx, filepath.Join(t.TempDir(), "watchdetect.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	return st, ctx
}

// putWatchItem persists one item whose document carries the given ffprobe
// and parsed fragments (verbatim ffprobe carries duration as a JSON string —
// the only shape a store round-trip decodes to).
func putWatchItem(t *testing.T, ctx context.Context, st *store.Store, id string, libraryID int64, ffprobe, parsed string) {
	t.Helper()
	doc := `{"ffprobe": ` + ffprobe + `, "parsed": ` + parsed + `}`
	if err := st.PutItem(ctx, store.Item{
		ID: id, ModuleID: "tv", LibraryID: libraryID, FileID: "f_" + id,
		Document: []byte(doc),
	}); err != nil {
		t.Fatalf("PutItem %s: %v", id, err)
	}
}

// drainRecsWake empties the wake channel and reports whether a poke was
// pending. The channel is package state shared with the janitor loop, so a
// test must never leave pokes behind for the next assertion.
func drainRecsWake(t *testing.T) bool {
	t.Helper()
	poked := false
	for {
		select {
		case <-recsWake:
			poked = true
		default:
			return poked
		}
	}
}

// watchedCount counts the learning queue rows the detector should have fed.
func watchedCount(t *testing.T, ctx context.Context, st *store.Store) int {
	t.Helper()
	itemIDs, _, _, _, err := st.ListUnappliedWatched(ctx)
	if err != nil {
		t.Fatalf("ListUnappliedWatched: %v", err)
	}
	return len(itemIDs)
}

// TestWatchDetectRecordsCompletion covers the delta's wired happy path: a
// position at ≥ 90% of the stored ffprobe duration inserts exactly ONE
// watched row — carrying the item's library and its parsed series anchor —
// and pokes the recs wake. A repeat write stays ONE row (PK idempotence) and
// the wake coalesces.
func TestWatchDetectRecordsCompletion(t *testing.T) {
	st, ctx := watchDetectFixture(t)
	putWatchItem(t, ctx, st, "it_ep", 3,
		`{"format": {"duration": "1450.109"}}`,
		`{"series_relative_path": "Code Geass"}`)
	drainRecsWake(t) // a clean wake slate

	detect := newWatchDetect(st)
	detect(ctx, "it_ep", 1400) // 96.5% of 1450.109 — past the 90% floor

	itemIDs, libraryIDs, seriesPaths, _, err := st.ListUnappliedWatched(ctx)
	if err != nil {
		t.Fatalf("ListUnappliedWatched: %v", err)
	}
	if len(itemIDs) != 1 || itemIDs[0] != "it_ep" {
		t.Fatalf("watched items = %v, want exactly [it_ep]", itemIDs)
	}
	if libraryIDs[0] != 3 {
		t.Fatalf("watched library_id = %d, want 3", libraryIDs[0])
	}
	if seriesPaths[0] != "Code Geass" {
		t.Fatalf("watched series path = %q, want %q", seriesPaths[0], "Code Geass")
	}
	if !drainRecsWake(t) {
		t.Fatal("recs wake not poked on completion insert")
	}

	// The repeat: the PK folds it to a no-op (still one row) and the wake's
	// capacity-1 buffer coalesces the second poke.
	detect(ctx, "it_ep", 1449)
	if got := watchedCount(t, ctx, st); got != 1 {
		t.Fatalf("watched rows after repeat = %d, want 1 (PK idempotence)", got)
	}
	if poked := drainRecsWake(t); !poked {
		t.Fatal("second completion did not poke the wake")
	}
	if poked := drainRecsWake(t); poked {
		t.Fatal("wake held more than one pending poke")
	}
}

// TestWatchDetectBelowThresholdSkips: a mid-episode position is not a
// completion — no row, no poke.
func TestWatchDetectBelowThresholdSkips(t *testing.T) {
	st, ctx := watchDetectFixture(t)
	putWatchItem(t, ctx, st, "it_mid", 1,
		`{"format": {"duration": "1450.109"}}`, `{}`)

	newWatchDetect(st)(ctx, "it_mid", 700) // 48% — well short of the floor

	if got := watchedCount(t, ctx, st); got != 0 {
		t.Fatalf("watched rows = %d, want 0 below the threshold", got)
	}
	if drainRecsWake(t) {
		t.Fatal("wake poked without a completion insert")
	}
}

