// TestOnProgressFanOutDispatchesBothLegs: the fan-out hands the SAME event to
// every non-nil leg, skips a nil leg without panicking (the per-leg nil
// safety the seam contract needs), and never blocks on a leg's internals.
func TestOnProgressFanOutDispatchesBothLegs(t *testing.T) {
	type call struct {
		itemID   string
		position int64
	}
	var thumb, watch []call
	thumbLeg := func(_ context.Context, itemID string, position int64) {
		thumb = append(thumb, call{itemID, position})
	}
	watchLeg := func(_ context.Context, itemID string, position int64) {
		watch = append(watch, call{itemID, position})
	}

	fanOut(thumbLeg, nil, watchLeg)(context.Background(), "itm_1", 1234)

	if len(thumb) != 1 || len(watch) != 1 {
		t.Fatalf("leg calls: thumb=%d watch=%d, want 1/1 (nil leg skipped, no panic)", len(thumb), len(watch))
	}
	if thumb[0] != (call{"itm_1", 1234}) || watch[0] != (call{"itm_1", 1234}) {
		t.Fatalf("legs saw %v / %v, want the same (itm_1, 1234) event", thumb, watch)
	}
}

// TestOnProgressFanOutWiredDetectorJoint drives the composition root's real
// shape — fanOut(newThumbRegrab(st, mgr), newWatchDetect(st)) over a real
// store — through the completion path: the detector leg inserts the watched
// row and pokes the wake while the thumb leg (no plugins loaded here) runs
// its log-and-skip beside it, proving the legs compose without the thumb
// path swallowing or failing the detector.
func TestOnProgressFanOutWiredDetectorJoint(t *testing.T) {
	st, ctx := watchDetectFixture(t)
	mgr := plugin.Open(plugin.Deps{})
	putWatchItem(t, ctx, st, "it_joint", 1,
		`{"format": {"duration": "3600"}}`, `{"series_relative_path": "Serial"}`)
	drainRecsWake(t)

	onProgress := fanOut(newThumbRegrab(st, mgr), newWatchDetect(st))
	onProgress(ctx, "it_joint", 3300) // 91.7% — completion

	itemIDs, _, seriesPaths, _, err := st.ListUnappliedWatched(ctx)
	if err != nil {
		t.Fatalf("ListUnappliedWatched: %v", err)
	}
	if len(itemIDs) != 1 || itemIDs[0] != "it_joint" || seriesPaths[0] != "Serial" {
		t.Fatalf("watched rows = %v/%v, want it_joint on Serial", itemIDs, seriesPaths)
	}
	if !drainRecsWake(t) {
		t.Fatal("recs wake not poked by the wired detector leg")
	}
}

// TestWatchDetectInsertCarriesTimestamp pins the ledger contract the janitor
// queue orders by: the detector stamps completedAt itself (the store never
// reads a clock), so an inserted row must carry a fresh, parseable
// completed_at inside the call window.
func TestWatchDetectInsertCarriesTimestamp(t *testing.T) {
	st, ctx := watchDetectFixture(t)
	putWatchItem(t, ctx, st, "it_ts", 1,
		`{"format": {"duration": "600"}}`, `{}`)

	before := time.Now().UTC().Add(-time.Second)
	newWatchDetect(st)(ctx, "it_ts", 600)
	after := time.Now().UTC().Add(time.Second)

	_, _, _, completed, err := st.ListUnappliedWatched(ctx)
	if err != nil {
		t.Fatalf("ListUnappliedWatched: %v", err)
	}
	if len(completed) != 1 {
		t.Fatalf("completed rows = %d, want 1", len(completed))
	}
	if completed[0].Before(before) || completed[0].After(after) {
		t.Fatalf("completed_at = %v, want within [%v, %v]", completed[0], before, after)
	}
	drainRecsWake(t)
}
